def icon(n):return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true">'+icons.get(n,icons['grid'])+'</svg>'
def link(url,label,cls='btn'):return f'<a class="{cls}" href="{url}">{label}<span aria-hidden="true">&#8599;</span></a>'
def cards(items):return '<div class="cards">'+''.join(f'<a class="card" href="{u}"><span class="ico">{icon(i)}</span><h3>{t}</h3><p>{d}</p><span class="card-link">Explore <span aria-hidden="true">&#8599;</span></span></a>' for u,t,d,i in items)+'</div>'
def section(k,t,p='',body='',cls=''):return f'<section class="{cls}"><div class="wrap"><div class="section-heading"><div><p class="eyebrow">{k}</p><h2>{t}</h2></div>'+ (f'<p class="section-intro">{p}</p>' if p else '')+f'</div>{body}</div></section>'
def faq(items):return '<div class="faq">'+''.join(f'<details><summary>{q}<span aria-hidden="true">+</span></summary><p>{a}</p></details>' for q,a in items)+'</div>'
def steps(items):return '<div class="steps">'+''.join(f'<article><span>0{i+1}</span><h3>{t}</h3><p>{d}</p></article>' for i,(t,d) in enumerate(items))+'</div>'
def hero(label,title,desc,action='Plan your project',url='/contact.html',visual=''):
 return f'<section class="page-hero"><div class="wrap hero-grid"><div><p class="eyebrow">{label}</p><h1>{title}</h1><p class="lead">{desc}</p><div class="actions">{link(url,action)}{link("/services.html","Explore services","btn ghost")}</div></div>{visual or "<div class=hero-note><span class=small>THE HEYDOCK APPROACH</span><p>The right people.<br>The right systems.<br>A clear way forward.</p><div class=note-line>Scope → Deliver → Support</div></div>"}</div></section>'
