 head=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{E(title)} | HeyDock</title><meta name="description" content="{E(desc)}"><meta name="theme-color" content="#142a35"><meta property="og:title" content="{E(title)} | HeyDock"><meta property="og:description" content="{E(desc)}"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/styles.css"><script src="/app.js" defer></script></head><body><a class="skip" href="#main">Skip to content</a><div class="preview-strip">Private preview <span>HeyDock · Contact delivery pending setup</span></div><header><div class="wrap nav"><a class="logo" href="/" aria-label="HeyDock home"><span class="logo-mark">h<span>·</span></span>HeyDock<span class="logo-dot">.</span></a><button class="menu-toggle" aria-label="Open navigation" aria-expanded="false" aria-controls="main-nav">Menu <span>☰</span></button><nav id="main-nav" aria-label="Main navigation">'''
 head+=''.join(f'<a href="{u}" '+('aria-current="page"' if active==u else '')+f'>{t}</a>' for u,t in nav)
