home+=section('02 / BUILT AROUND YOU','Your team, extended.','Two ways to work with HeyDock. The same focus on clear responsibilities and practical delivery.','''<div class="audience-grid"><article><span class="label">FOR IT COMPANIES</span><h3>Your expertise.<br>Our delivery capacity.</h3><p>White-label engineering, remote specialists and project support that fit your customer relationships.</p>'''+link('/partners.html','Explore partnerships','text-link')+'''</article><article><span class="label">FOR BUSINESSES</span><h3>Less IT friction.<br>More room to work.</h3><p>Get support, implement business software or build something new with a single delivery contact.</p>'''+link('/solutions.html','Explore business solutions','text-link')+'</article></div>','pale')
